@using sv_697e4cb6c4d94e31bbfc20b7adb3b0b8.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<div class="warehouse-selector">
    <label for="warehouse-select" class="form-label mb-0 me-2 text-white">Site:</label>
    <select id="warehouse-select"
            class="form-select form-select-sm"
            value="@WarehouseState.CurrentWarehouseId"
            @onchange="OnWarehouseSelected">
        @foreach (var wh in WarehouseState.GetWarehouses())
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var selected = e.Value?.ToString();
        if (!string.IsNullOrEmpty(selected))
        {
            WarehouseState.SetWarehouse(selected);
        }
    }

    // Re-render if another component changes the warehouse
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

@using sv_697e4cb6c4d94e31bbfc20b7adb3b0b8.Services
@inject InventoryAlertService AlertService
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<span class="alert-badge" title="Low-stock items">
    @if (AlertService.LastLowStockCount > 0)
    {
        <span class="badge bg-danger">@AlertService.LastLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success">0</span>
    }
</span>

@code {
    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private void HandleAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        // When warehouse changes, the count resets visually on next poll
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

