+    </div>
+    <div class="card-body">
+        <h5 class="card-title">Low-Stock Alerts</h5>
+        <p class="card-text">
+            Items below minimum level:
+            <span class="badge @(lowStockCount > 5 ? "bg-danger" : lowStockCount > 0 ? "bg-warning text-dark" : "bg-success") fs-5">
+                @lowStockCount
+            </span>
+        </p>
+        <p class="text-muted">
+            <small>Polling every 10 seconds. Last checked: @lastChecked.ToString("HH:mm:ss")</small>
+        </p>
+    </div>
+</div>
+
+@code {
+    private int lowStockCount;
+    private DateTime lastChecked = DateTime.Now;
+    private string currentWarehouseName = "";
+    private Timer? _pollingTimer;
+
+    protected override void OnInitialized()
+    {
+        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
+        AlertService.OnAlertCountChanged += HandleAlertCountChanged;
+
+        UpdateWarehouseName();
+        StartPolling();
+    }
+
+    private void StartPolling()
+    {
+        _pollingTimer = new Timer(async _ => await PollAlerts(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
+    }
+
+    private async Task PollAlerts()
+    {
+        var count = await AlertService.GetLowStockCountAsync(WarehouseState.CurrentWarehouseId);
+        lastChecked = DateTime.Now;
+
+        // Publish to all subscribers (including sidebar badge)
+        AlertService.PublishNewCount(count);
+    }
+
+    private void HandleWarehouseChanged()
+    {
+        UpdateWarehouseName();
+
+        // Reset timer to poll immediately for the new warehouse
+        _pollingTimer?.Change(TimeSpan.Zero, TimeSpan.FromSeconds(10));
+
+        InvokeAsync(StateHasChanged);
+    }
+
+    private void HandleAlertCountChanged()
+    {
+        lowStockCount = AlertService.LastLowStockCount;
+        InvokeAsync(StateHasChanged);
+    }
+
+    private void UpdateWarehouseName()
+    {
+        var wh = WarehouseState.GetWarehouses()
+            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
+        currentWarehouseName = wh?.Name ?? WarehouseState.CurrentWarehouseId;
+    }
+
+    public void Dispose()
+    {
+        _pollingTimer?.Dispose();
+        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
+        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;
+    }
+}
